  ('c0b58c13-1c57-4a4f-965d-19ead9b0c4d5', 'e758c989-6c02-4b91-a731-9d86f95cf82a', null, 'topic'::public.curated_course_node_type, 'Power System Fundamentals and Three-Phase Power', 'Builds the language of electric power: why grids use sinusoidal three-phase quantities, how real/reactive/apparent power are interpreted, and how balanced and unbalanced operating conditions are represented.', 0),
